"""Self-contained, same-origin admin console for the licensing server."""

ADMIN_HTML = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>直播复盘侠 - 授权管理台</title><style>
:root{color-scheme:light;font-family:"Microsoft YaHei",system-ui,sans-serif;color:#14213d;background:#f3f7fc}*{box-sizing:border-box}body{margin:0;min-width:1040px}.top{height:66px;background:#fff;border-bottom:1px solid #e5ecf7;display:flex;align-items:center;justify-content:space-between;padding:0 32px}.brand{font-size:19px;font-weight:800}.brand i{color:#3977ff;font-style:normal;margin-right:10px}.sub{font-size:12px;color:#8492aa;margin-top:4px}.auth{display:flex;align-items:center;gap:9px}.auth input{width:280px}.page{padding:24px 32px;max-width:1550px;margin:auto}.notice{background:#edf5ff;border:1px solid #cfe0ff;border-radius:8px;padding:12px 15px;color:#4d6386;font-size:13px;margin-bottom:16px}.grid{display:grid;grid-template-columns:390px 1fr;gap:16px}.card{background:#fff;border:1px solid #e5ecf7;border-radius:8px;padding:18px;box-shadow:0 4px 15px #1d3f762e}.card h2{font-size:16px;margin:0 0 15px;padding-left:10px;border-left:3px solid #3c8dff}.field{margin:12px 0}.field label{display:block;font-size:13px;font-weight:700;margin-bottom:7px}.field span{font-size:12px;color:#8492aa;font-weight:400;margin-left:6px}input,textarea,select{font:inherit;width:100%;padding:9px 10px;border:1px solid #ced9e9;border-radius:6px;outline:none}input:focus,textarea:focus{border-color:#4d86ff;box-shadow:0 0 0 3px #4d86ff18}.features{display:flex;flex-wrap:wrap;gap:7px}.features label{border:1px solid #dce6f4;border-radius:15px;padding:5px 8px;font-size:12px;color:#52647f}.features input{width:auto;margin-right:4px}button{border:0;border-radius:6px;background:#3977ff;color:#fff;padding:9px 13px;font:inherit;cursor:pointer}button:hover{background:#2866ee}button.ghost{background:#fff;border:1px solid #cdd9eb;color:#3866b2}button.warn{background:#ed6a5f}button.warn:hover{background:#db554a}button.small{padding:5px 8px;font-size:12px}.issue{display:flex;gap:8px;margin-top:15px}.issued{display:none;margin-top:13px;border-radius:7px;background:#e7fff1;color:#176342;padding:10px;font-size:13px}.issued code{display:block;color:#132d51;background:#fff;padding:7px;margin-top:6px;border-radius:5px;word-break:break-all}.headrow{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.headrow h2{margin:0}.muted{font-size:12px;color:#8492aa}.status{font-size:13px;min-height:19px;color:#5c6f8d}.status.bad{color:#c23e35}.table-wrap{overflow:auto;max-height:335px;border:1px solid #e7eef8;border-radius:7px}table{border-collapse:collapse;width:100%;font-size:13px}th{text-align:left;background:#f7faff;color:#70809a;font-weight:600;white-space:nowrap}td,th{padding:11px 12px;border-bottom:1px solid #edf1f7;vertical-align:middle}tr:last-child td{border-bottom:0}.tag{display:inline-block;background:#edf3ff;color:#3c68c4;border-radius:12px;padding:3px 7px;font-size:11px;margin:1px}.state-active{color:#1e9b5c;font-weight:700}.state-frozen{color:#d35a4e;font-weight:700}.state-unbound{color:#8a98ad;font-weight:700}.actions{white-space:nowrap}.empty{text-align:center;color:#9aa7ba;padding:32px}.mono{font-family:ui-monospace,Consolas,monospace;font-size:12px}.footer{font-size:12px;color:#8795aa;padding-top:18px}
</style></head><body><header class="top"><div><div class="brand"><i>◉</i>直播复盘侠 · 授权管理台</div><div class="sub">发卡、设备绑定、冻结与解绑</div></div><div class="auth"><input id="token" type="password" placeholder="输入管理员令牌（不会保存）"><button id="connect" class="ghost">连接管理台</button></div></header><main class="page"><div class="notice">管理员令牌仅保存在当前页面内存，刷新或关闭页面即清除。卡密只会在创建成功时显示一次，请立即交付给客户并妥善保存。</div><div id="status" class="status">请先输入管理员令牌并连接。</div><div class="grid"><section class="card"><h2>创建卡密</h2><div class="field"><label>授权功能</label><div class="features" id="features"><label><input type="checkbox" value="basic" checked>基础功能</label><label><input type="checkbox" value="live_monitor" checked>直播监听</label><label><input type="checkbox" value="export" checked>数据导出</label><label><input type="checkbox" value="ai_replay" checked>AI复盘</label><label><input type="checkbox" value="short_video_ai" checked>短视频AI</label><label><input type="checkbox" value="lead_radar" checked>AI获客</label><label><input type="checkbox" value="batch" checked>批量操作</label></div></div><div class="field"><label>设备数量 <span>默认一台电脑</span></label><select id="maxDevices"><option value="1">1 台</option><option value="2">2 台</option><option value="3">3 台</option><option value="5">5 台</option></select></div><div class="field"><label>同时监听上限 <span>由云端授权控制</span></label><select id="maxActiveRooms"><option value="3">3 个</option><option value="5">5 个</option><option value="10" selected>10 个</option><option value="15">15 个</option><option value="20">20 个</option></select></div><div class="field"><label>导出水印</label><div class="features"><label><input id="exportWatermark" type="checkbox" checked>导出文件写入授权标识</label></div></div><div class="field"><label>最低版本 <span>低于此版本可远程要求升级，可留空</span></label><input id="forceUpgradeBelow" maxlength="64" placeholder="例如 1.0.3"></div><div class="field"><label>备注 <span>例如客户名称、订单号</span></label><textarea id="note" rows="3" maxlength="500" placeholder="仅管理员可见"></textarea></div><div class="issue"><button id="issue">生成卡密</button></div><div class="issued" id="issued">请复制并保存这张卡密：<code id="issuedKey"></code><button class="small ghost" id="copyKey">复制卡密</button></div></section><section class="card"><div class="headrow"><h2>卡密与设备</h2><div><button class="small ghost" id="copyPublicKey">复制构建公钥</button> <button class="small ghost" id="refresh">刷新列表</button></div></div><div class="muted">只显示卡密前缀，不会回显完整卡密。构建公钥可公开，只用于安装包验签授权，不包含服务器私钥。</div><h3>卡密列表</h3><div class="table-wrap"><table><thead><tr><th>卡密前缀</th><th>功能</th><th>策略</th><th>已绑/上限</th><th>备注</th><th>状态</th></tr></thead><tbody id="cards"><tr><td colspan="6" class="empty">等待加载</td></tr></tbody></table></div><h3>设备授权记录</h3><div class="table-wrap"><table><thead><tr><th>卡密</th><th>设备编号</th><th>客户端</th><th>最后刷新</th><th>状态</th><th>操作</th></tr></thead><tbody id="activations"><tr><td colspan="6" class="empty">等待加载</td></tr></tbody></table></div></section></div><div class="footer">冻结后，客户的联网客户端会在下一次授权刷新时停止商业功能；设备离线时仍受本机签名授权有效期限制。</div></main><script>
let adminToken=''; const $=id=>document.getElementById(id); const status=(text,bad=false)=>{const el=$('status');el.textContent=text;el.className='status'+(bad?' bad':'')};
const fmt=t=>t?new Date(t*1000).toLocaleString('zh-CN',{hour12:false}):'长期'; const esc=v=>String(v??'');
async function api(path,opts={}){const headers={...(opts.headers||{}),Authorization:'Bearer '+adminToken};const r=await fetch(path,{...opts,headers});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.detail||'请求失败');return data}
function cell(text,cls=''){const td=document.createElement('td');td.textContent=esc(text);if(cls)td.className=cls;return td}
function tags(items){const box=document.createElement('td');(items||[]).forEach(x=>{const t=document.createElement('i');t.className='tag';t.textContent=x;box.appendChild(t)});return box}
function renderCards(cards){const body=$('cards');body.textContent='';if(!cards.length){body.innerHTML='<tr><td colspan="6" class="empty">暂无卡密</td></tr>';return}cards.forEach(c=>{const policy=c.policy||{};const tr=document.createElement('tr');tr.append(cell(c.key_prefix+'…','mono'),tags(c.features),cell('监听 '+(policy.max_active_rooms||10)+' 个'+(policy.export_watermark?' / 水印':'')),cell((c.active_devices||0)+' / '+c.max_devices),cell(c.note||'—'),cell(c.status,c.status==='active'?'state-active':'state-frozen'));body.appendChild(tr)})}
function renderActivations(rows){const body=$('activations');body.textContent='';if(!rows.length){body.innerHTML='<tr><td colspan="6" class="empty">暂无设备授权记录</td></tr>';return}rows.forEach(a=>{const tr=document.createElement('tr');tr.append(cell(a.key_prefix+'…','mono'),cell((a.device_hash||'').slice(0,16)+'…','mono'),cell(a.app_version||'—'),cell(fmt(a.last_seen_at)),cell(a.status,'state-'+a.status));const actions=document.createElement('td');actions.className='actions';if(a.status==='active'){const freeze=document.createElement('button');freeze.className='small warn';freeze.textContent='冻结';freeze.onclick=()=>changeState(a.id,'freeze');actions.appendChild(freeze)}if(a.status!=='unbound'){const unbind=document.createElement('button');unbind.className='small ghost';unbind.textContent='解绑';unbind.style.marginLeft='5px';unbind.onclick=()=>changeState(a.id,'unbind');actions.appendChild(unbind)}tr.append(actions);body.appendChild(tr)})}
async function load(){if(!adminToken)return;try{status('正在读取授权数据…');const [cards,acts]=await Promise.all([api('/admin/cards'),api('/admin/activations')]);renderCards(cards.cards||[]);renderActivations(acts.activations||[]);status('已连接，可管理 '+(cards.cards||[]).length+' 张卡密与 '+(acts.activations||[]).length+' 台设备。')}catch(e){status(e.message||'连接失败',true)}}
async function changeState(id,action){const reason=prompt(action==='freeze'?'冻结原因（可选）：':'解绑原因（可选）：','')||'';try{await api('/admin/activations/'+id+'/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});status(action==='freeze'?'设备已冻结。':'设备已解绑。');load()}catch(e){status(e.message,true)}}
$('connect').onclick=()=>{adminToken=$('token').value.trim();if(!adminToken)return status('请输入管理员令牌。',true);load()};$('refresh').onclick=load;$('issue').onclick=async()=>{if(!adminToken)return status('请先连接管理台。',true);const features=[...document.querySelectorAll('#features input:checked')].map(x=>x.value);if(!features.length)return status('至少选择一个授权功能。',true);try{const r=await api('/admin/card-keys',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({features,max_devices:Number($('maxDevices').value),max_active_rooms:Number($('maxActiveRooms').value),export_watermark:$('exportWatermark').checked,force_upgrade_below:$('forceUpgradeBelow').value,note:$('note').value})});$('issuedKey').textContent=r.card_key;$('issued').style.display='block';status('卡密已生成，请立即复制并保存。');load()}catch(e){status(e.message,true)}};$('copyKey').onclick=async()=>{try{await navigator.clipboard.writeText($('issuedKey').textContent);status('卡密已复制。')}catch(e){status('复制失败，请手动复制。',true)}};
$('copyPublicKey').onclick=async()=>{if(!adminToken)return status('请先连接管理台。',true);try{const r=await api('/admin/public-key');await navigator.clipboard.writeText(r.public_key);status('商业构建公钥已复制，可用于安装包构建。')}catch(e){status(e.message||'复制公钥失败',true)}};
</script></body></html>"""
